use ferroui_base::{controls::ResourceKey, metadata::from_markup_value, styling::ControlTheme, Ref, TypeInfo, Visual};
use ferroui_controls::{Application, Button, NavigationView, ScrollViewer, Slider};
use ferroui_controls::primitives::TemplatedControl;
use ferroui_themes_winui::WinUITheme;
#[repr(C)]
struct Timespec { seconds: i64, nanoseconds: i64 }
unsafe extern "C" { fn clock_gettime(clock: i32, value: *mut Timespec) -> i32; }

fn thread_cpu_ns() -> i64 {
    let mut value = Timespec { seconds: 0, nanoseconds: 0 };
    assert_eq!(unsafe { clock_gettime(3, &mut value) }, 0);
    value.seconds * 1_000_000_000 + value.nanoseconds
}

#[cfg(feature = "retain-archive")]
fn load_archive(path: std::ffi::OsString) -> ferroui_base::Ref<WinUITheme> {
    use ferroui_base::{metadata::from_markup_value, utilities::Uri};
    use ferroui_markup_xaml::RuntimeXamlLoaderConfiguration;
    use ferroui_markup_xaml_loader::{
        binary_document::pack::{expand_solid, is_solid, ThemePack},
        FerroRuntimeXamlLoader,
    };

    let image = std::fs::read(path).expect("read replacement archive");
    #[cfg(feature = "operand-updates")]
    if image.starts_with(b"FXU\x01") {
        return ferroui_themes_winui::load_theme_update(&image).expect("load compiled operands");
    }
    ferroui_themes_winui::register_types();
    let mut config = RuntimeXamlLoaderConfiguration::new();
    config.local_assembly = Some(&ferroui_themes_winui::ASSEMBLY);
    let uri = Uri::absolute(WinUITheme::DOCUMENT_URI).unwrap();
    let root = ferroui_themes_winui::compiled_archive_root();
    #[cfg(feature = "legacy-archive")]
    let native = root.try_load(&image, &uri, &config, None);
    #[cfg(not(feature = "legacy-archive"))]
    let native = FerroRuntimeXamlLoader::try_load_compiled_archive(&root, &image, &uri, &config, None);
    if let Some(value) = native.expect("load compiled archive") {
        return from_markup_value(&Some(value)).expect("compiled WinUI theme class");
    }
    let indexed = if is_solid(&image) {
        expand_solid(&image).unwrap()
    } else {
        image
    };
    let archive = ThemePack::open(&indexed).unwrap();
    let value =
        FerroRuntimeXamlLoader::load_packed_document(&archive, uri, None, None, config).unwrap();
    from_markup_value(&Some(value)).expect("WinUI theme class")
}


fn count_visuals(visual: &Visual) -> usize {
    1 + visual.visual_children_snapshot().map_or(0, |children|
        children.iter().map(|child| count_visuals(child)).sum())
}

fn activate(theme: &Ref<ControlTheme>, new_control: fn() -> Ref<TemplatedControl>) -> usize {
    let control = new_control();
    control.set_theme(theme);
    control.apply_styling();
    control.apply_template();
    assert_eq!(control.visual_children_count(), 1, "the template must produce one visual root");
    count_visuals(&control)
}

fn main() {
    let app = Application::new();
    Application::bind_current(app.clone());
    #[cfg(feature = "retain-archive")]
    let theme = std::env::args_os().nth(1).map_or_else(WinUITheme::new, load_archive);
    #[cfg(not(feature = "retain-archive"))]
    let theme = WinUITheme::new();
    app.styles().add(theme.as_style());
    let factories: [(&TypeInfo, fn() -> Ref<TemplatedControl>); 4] = [
        (Button::TYPE, || Button::new().upcast()),
        (ScrollViewer::TYPE, || ScrollViewer::new().upcast()),
        (NavigationView::TYPE, || NavigationView::new().upcast()),
        (Slider::TYPE, || Slider::new().upcast()),
    ];
    for (ty, create) in factories {
        let value = theme.try_get_resource(&ResourceKey::Type(ty), None).flatten();
        let style = from_markup_value::<Ref<ControlTheme>>(&value).expect("typed theme");
        assert!(style.target_type().is_some_and(|t| std::ptr::eq(ty,t)));
        let start = thread_cpu_ns();
        let count = activate(&style,create);
        let first = thread_cpu_ns() - start;
        let start = thread_cpu_ns();
        for _ in 0..12 {assert_eq!(activate(&style,create),count);}
        println!("{} {count} {first} {}",ty.name(),(thread_cpu_ns() - start)/12);
    }
}
